import { exhibitionSourcePresentation } from './exhibitionSourcePresentation.js';
import { fragments } from '../data/fragments.js';
import { cleanViewClosing } from './viewClosing.js';
import { decodeViewText } from './viewText';
import { cleanExhibitionCues, cleanExhibitionIntro, exhibitionParagraphs } from './exhibitionCues.js';
import { createGalleryArchitecture, galleryAreaAt, galleryCanStand } from './exhibitionArchitecture.js';
import { exhibitionLayoutSeed } from './exhibitionFloorplan.js';
import { exhibitionComponentPreview } from './exhibitionComponentPreview.js';

function carrierFor(stop, view) {
  const kind = stop.source?.entity?.kind;
  const seed = `${view.question || view.title}|${stop.source?.id || stop.block?.source_id || stop.id}`;
  let hash = 2166136261;
  for (const character of seed) hash = Math.imul(hash ^ character.charCodeAt(0), 16777619) >>> 0;
  hash = (hash ^ (hash >>> 16)) >>> 0;
  if (kind === 'fragment') {
    const category = stop.source.entity.category || fragments.find(fragment => fragment.id === stop.source.entity.id)?.category;
    const options = category === 'life' ? ['hanging-scroll', 'folio'] : ['reading-case', 'folio'];
    return options[hash % options.length];
  }
  if (['research', 'publication', 'education', 'experience'].includes(kind)) return ['folio', 'hanging-scroll'][hash % 2];
  return 'folio';
}

export const EXHIBITION_ROOM_WIDTH = 15.4;

export function exhibitionText(value) {
  return decodeViewText(value).replace(/\s*\[[a-z0-9_-]+:[^\]]+\]/gi, '').trim();
}

export function exhibitionPlaces(stop) {
  const source = stop.source || {};
  const media = new Map((source.media || []).map(item => [item.alt, item]));
  return (source.entity?.places || []).map(place => {
    const image = media.get(place.en);
    return { ...place, preview: image?.src || place.preview || place.img, img: image?.fullSrc || image?.src || place.img };
  });
}

// The saved View remains the single document. Each stop retains its exact
// position so changing presentation never regenerates or edits the reading.
export function createViewExhibition(view, sourceFor, guide = null) {
  const closing = cleanViewClosing(view?.closing || guide?.closing);
  const stops = [];
  for (const [sectionIndex, section] of (view?.sections || []).entries()) {
    for (const [blockIndex, block] of (section.blocks || []).entries()) {
      if (block.kind !== 'source') continue;
      const source = sourceFor(block.source_id);
      const parts = source?.parts || [];
      const selected = block.part_indices?.length ? block.part_indices.map(index => parts[index]).filter(Boolean) : parts;
      const images = (source?.media || []).filter(media => media.src && media.kind !== 'video');
      const kind = source?.entity?.places?.length ? 'globe'
        : ['interactive', 'embed'].includes(block.presentation) ? 'interactive'
        : images.length && source?.entity?.mediaMode !== 'logo' ? 'photograph' : 'reading';
      const display=exhibitionSourcePresentation({title:exhibitionText(source?.title || section.heading || view.title),page:source?.page === 'Projects' ? 'Builds' : source?.page || '',source,texts:selected.map(exhibitionText)});
      stops.push({
        id: `${sectionIndex}-${blockIndex}`, sectionIndex, blockIndex, block, source,
        heading: exhibitionText(section.heading), title: exhibitionText(source?.title || section.heading || view.title),
        narrative: [],
        texts: selected.map(exhibitionText), display, images, kind,
        componentPreview: exhibitionComponentPreview(source, block),
        page: display.eyebrow,
      });
    }
  }
  const rooms = [];
  let front = -6;
  const arranged = [];
  for (const [sectionIndex, section] of (view?.sections || []).entries()) {
    if (!(section.blocks || []).some(block => ['bridge', 'source'].includes(block.kind))) continue;
    const contents = stops.filter(stop => stop.sectionIndex === sectionIndex);
    const depth = Math.max(20, contents.length * 4.2 + 10);
    const room = { index: rooms.length, sectionIndex, title: exhibitionText(section.heading || view.title), narrative: [], front, back: front - depth, depth, doorX: rooms.length % 2 ? -1.25 : 1.25, stopIndices: [] };
    contents.forEach((stop, localIndex) => {
      const form = stop.kind === 'globe' ? 'globe'
        : stop.componentPreview ? stop.componentPreview.form
        : stop.source?.entity?.kind === 'gallery' && stop.images.length >= 4 ? 'photo-carousel'
        : stop.source?.entity?.kind === 'gallery' && stop.images.length > 1 ? 'light-table'
        : stop.source?.entity?.kind === 'fragment' ? carrierFor(stop, view)
        : ['project', 'early-project'].includes(stop.source?.entity?.kind) ? 'screen'
        : stop.kind === 'photograph' ? 'photographs'
        : carrierFor(stop, view);
      const floor = form !== 'photographs';
      const side = localIndex % 2 ? 1 : -1;
      const z = front - 7.7 - localIndex * 4.15;
      const isEndWall = !closing && !floor && contents.length > 2 && localIndex === contents.length - 1;
      const viewingHeight = form === 'hanging-scroll' ? 2.6 : form === 'reading-case' ? 1.25 : form === 'folio' ? 1.9 : floor ? 1.6 : 2.65;
      const anchor = isEndWall ? [0, 2.65, room.back + .24] : [side * (floor ? 3.4 : 7.43), viewingHeight, z];
      const eye = isEndWall ? [0, 1.72, room.back + 6.1] : [floor ? side * .8 : side * 1.8, 1.72, z + (floor ? 3.8 : 2.6)];
      const index = arranged.length;
      room.stopIndices.push(index);
      arranged.push({ ...stop, index, form, floor, side, z, anchor, eye, rotation: isEndWall ? 0 : -side * Math.PI / 2, roomIndex: room.index });
    });
    // The introduction belongs to the exhibition only. Older public Views can
    // receive a separate, heading-checked guide without editing their article.
    const supplement = guide?.sections?.find(item => item.heading === section.heading);
    room.introduction = cleanExhibitionIntro(section.exhibition_intro || supplement?.introduction);
    room.introAnchor = [room.doorX - 3.95, 2.7, room.front + .145];
    room.introEye = [room.doorX - 1.7, 1.72, room.front + 4.2];
    rooms.push(room);
    front = room.back;
  }
  const steps = [];
  for (const room of rooms) {
    const section = view.sections[room.sectionIndex];
    const sourceIndices = new Map(room.stopIndices.map(index => [arranged[index].block.source_id, index]));
    room.stepIndices = [];
    const append = step => {
      const index = steps.length;
      steps.push({ ...step, index, roomIndex: room.index, sectionIndex: room.sectionIndex });
      room.stepIndices.push(index);
      return index;
    };
    room.introStep = append({ kind: 'introduction', stopIndex: -1, blockIndex: -1, highlight: false });
    let focusIndex = -1;
    for (const [blockIndex, block] of (section.blocks || []).entries()) {
      if (block.kind !== 'bridge') continue;
      const cues = cleanExhibitionCues(block.exhibition_cues, block.text, new Set(sourceIndices.keys()));
      const paragraphs = exhibitionParagraphs(exhibitionText(block.text));
      const following = section.blocks[blockIndex + 1];
      for (const [paragraph, text] of paragraphs.entries()) {
        const cue = cues.find(item => item.paragraph === paragraph);
        let highlight = false;
        if (cue) {
          if (cue.focus_source_id) focusIndex = sourceIndices.get(cue.focus_source_id);
          highlight = cue.highlight && focusIndex >= 0;
        } else {
          // Legacy documents offer structural hints only. A following source
          // establishes a focus, while later reflections retain that location.
          const next = following?.kind === 'source' ? sourceIndices.get(following.source_id) : undefined;
          if (next !== undefined) { focusIndex = next; highlight = true; }
        }
        const key = `${blockIndex}-${paragraph}`;
        const stepIndex = append({ kind: 'passage', key, blockIndex, paragraph, stopIndex: focusIndex, highlight });
        room.narrative.push({ key, text, blockIndex, paragraph, stepIndex });
      }
    }
    // A source-only legacy section still offers a guided visit to its works.
    if (!room.narrative.length) for (const stopIndex of room.stopIndices) append({ kind: 'work', stopIndex, blockIndex: arranged[stopIndex].blockIndex, highlight: false });
  }
  if (closing && rooms.length) {
    const room = rooms.at(-1);
    closing.anchor = [-2.3, 2.8, room.back + .15];
    closing.target = [...closing.anchor];
    closing.eye = [-2.3, 1.85, room.back + 6.4];
    closing.notesPosition = [-.55, 0, room.back + 2.6];
    closing.stepIndex = steps.length;
    steps.push({ index: steps.length, kind: 'closing', roomIndex: room.index, sectionIndex: view.sections.length, blockIndex: -2, stopIndex: -1, highlight: false });
  }
  const items = [...new Map(arranged.filter(stop => stop.source).map(stop => [stop.source.source_id || stop.block.source_id, stop])).values()]
    .map(stop => ({ id: stop.source.source_id || stop.block.source_id, title: stop.title, page: stop.page, stopIndex: stop.index }));
  let citations = null;
  if (items.length && rooms.length) {
    const room = rooms.at(-1);
    const chapters = rooms.map(room => ({
      heading: room.title,
      sectionIndex: room.sectionIndex,
      itemIndices: [...new Set(room.stopIndices.map(index => items.findIndex(item => item.id === (arranged[index].source?.source_id || arranged[index].block.source_id))).filter(index => index >= 0))],
    })).filter(chapter => chapter.itemIndices.length);
    citations = { items, chapters, anchor: [7.43, 2.75, room.back + 5.1], eye: [2, 1.85, room.back + 5.1], stepIndex: steps.length };
    steps.push({ index: steps.length, kind: 'citations', roomIndex: room.index, sectionIndex: view.sections.length, blockIndex: -3, stopIndex: -1, highlight: false });
  }
  const seed = exhibitionLayoutSeed(JSON.stringify([view.question, view.title, rooms.map(room => [room.title, room.stopIndices.length]), arranged.map(stop => stop.id)]));
  const families = rooms.length < 3 ? ['linear', 'corner'] : ['linear', 'corner', 'courtyard'];
  const architecture = createGalleryArchitecture(rooms, arranged, closing, citations, [], { seed, family: families[seed % families.length] });
  return {
    steps, closing, citations, architecture,
    title: exhibitionText(view?.title), question: exhibitionText(view?.question), dek: exhibitionText(view?.dek),
    illustration: view?.illustration?.src || '',
    stops: arranged, rooms, width: EXHIBITION_ROOM_WIDTH, front: 8.5, back: Math.min(-12, front),
  };
}

export function exhibitionStopForPosition(exhibition, sectionIndex, blockIndex) {
  const exact = exhibition.stops.findIndex(stop => stop.sectionIndex === sectionIndex && stop.blockIndex === blockIndex);
  if (exact >= 0) return exact;
  const room = exhibition.rooms.find(item => item.sectionIndex === sectionIndex);
  // Article positions select a nearby viewing position without assigning the
  // narrative to that work. The room keeps its independent, ordered passages.
  return room?.stopIndices.find(index => exhibition.stops[index].blockIndex > blockIndex) ?? room?.stopIndices.at(-1) ?? -1;
}

export function exhibitionCamera(stop, close = false) {
  if (!stop) return { eye: [-.1, 1.72, 7.2], target: [-3.6, 2.4, .1] };
  return {
    eye: close ? stop.eye.map((value, i) => i === 1 ? 1.72 : value + (stop.anchor[i] - value) * .38) : [...stop.eye],
    target: [...(stop.target || stop.anchor)],
    flat: !stop.floor || stop.form === 'hanging-scroll',
  };
}

export function exhibitionRoomAt(exhibition, z, x = 0) {
  if (exhibition.architecture) return galleryAreaAt(exhibition.architecture, x, z)?.chapterIndex ?? -1;
  return exhibition.rooms.find(room => z <= room.front && z >= room.back)?.index ?? -1;
}

// Keep the walking surface separate from the visual geometry. Small movements
// resolve along each axis, allowing the reader to slide naturally along walls.
export function exhibitionCanStand(exhibition, x, z) {
  if (exhibition.architecture) return galleryCanStand(exhibition.architecture, x, z);
  const radius = .3;
  if (Math.abs(x) > exhibition.width / 2 - .3 - radius || z > exhibition.front - radius || z < exhibition.back + radius) return false;
  for (const room of exhibition.rooms) {
    if (Math.abs(z - room.front) < .16 + radius && Math.abs(x - room.doorX) > 1.85 - radius) return false;
  }
  // The entrance wall and the physical footprints of the installations.
  if (x > -6.65 && x < -.85 && Math.abs(z - .1) < .44) return false;
  return !exhibition.stops.some(stop => stop.floor && Math.abs(x - stop.anchor[0]) < 2 && Math.abs(z - stop.anchor[2]) < 1.7);
}

export function exhibitionStepForPosition(exhibition, sectionIndex, blockIndex) {
  return exhibition.steps.findIndex(step => step.sectionIndex === sectionIndex && step.blockIndex === blockIndex);
}

export function exhibitionStepForWork(exhibition, stopIndex, currentStep = -1) {
  const current = exhibition.steps[currentStep];
  if (current?.stopIndex === stopIndex) return currentStep;
  const found = exhibition.steps.findIndex(step => step.stopIndex === stopIndex);
  return found >= 0 ? found : exhibition.rooms[exhibition.stops[stopIndex]?.roomIndex]?.introStep ?? -1;
}

export function formatExhibitionDate(value, language = '') {
  if (!value) return '';
  const date = new Date(value);
  if (!Number.isFinite(date.getTime())) return '';
  const options = { day: 'numeric', month: 'long', year: 'numeric', timeZone: 'UTC' };
  try { return new Intl.DateTimeFormat(!language || /^en(?:-|$)/.test(language) ? 'en-GB' : language, options).format(date); }
  catch { return new Intl.DateTimeFormat('en-GB', options).format(date); }
}
